import{_ as t,o as a,c as i,a9 as o}from"./chunks/framework.asyjyako.js";const u=JSON.parse('{"title":"Companion APIs","description":"","frontmatter":{},"headers":[],"relativePath":"reference/optional-api.md","filePath":"reference/optional-api.md","lastUpdated":null}'),r={name:"reference/optional-api.md"};function n(l,e,d,p,s,c){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="Companion-APIs" tabindex="-1">Companion APIs <a class="header-anchor" href="#Companion-APIs" aria-label="Permalink to &quot;Companion APIs {#Companion-APIs}&quot;">​</a></h1><p>These Public and Full references render the real Julia docstrings of the optional packages from the same source revision as this Core 1.0.1 site. Each owner is loaded in a separate documentation project. Full API includes documented internal bindings; it does not promise documentation for every private helper.</p><table><thead><tr><th>Owner</th><th>Public API</th><th>Full API</th><th>Reference inventory</th></tr></thead><tbody><tr><td>PerfCheckerLinuxPerf 1.0.1</td><td><a href="../optional-api/linuxperf/public-api.html">Public</a></td><td><a href="../optional-api/linuxperf/full-api.html">Full</a></td><td><a href="../optional-api/linuxperf.inv">Inventory</a></td></tr><tr><td>PerfCheckerLIKWID 1.0.1</td><td><a href="../optional-api/likwid/public-api.html">Public</a></td><td><a href="../optional-api/likwid/full-api.html">Full</a></td><td><a href="../optional-api/likwid.inv">Inventory</a></td></tr><tr><td>PerfCheckerMakie 1.0.1</td><td><a href="../optional-api/makie/public-api.html">Public</a></td><td><a href="../optional-api/makie/full-api.html">Full</a></td><td><a href="../optional-api/makie.inv">Inventory</a></td></tr><tr><td>PerfCheckerWeb 1.0.0</td><td><a href="../optional-api/web/public-api.html">Public</a></td><td><a href="../optional-api/web/full-api.html">Full</a></td><td><a href="../optional-api/web.inv">Inventory</a></td></tr><tr><td>PerfCheckerPluto 1.0.1</td><td><a href="../optional-api/pluto/public-api.html">Public</a></td><td><a href="../optional-api/pluto/full-api.html">Full</a></td><td><a href="../optional-api/pluto.inv">Inventory</a></td></tr><tr><td>PerfCheckerTachikoma 1.0.1</td><td><a href="../optional-api/tachikoma/public-api.html">Public</a></td><td><a href="../optional-api/tachikoma/full-api.html">Full</a></td><td><a href="../optional-api/tachikoma.inv">Inventory</a></td></tr></tbody></table><p>The <a href="./public-api">Core Public API</a> and <a href="./api">Core Full API</a> document Core&#39;s bindings. A companion can define methods of a Core binding: for example, PerfCheckerWeb defines methods of <code>PerfChecker.serve_suite</code>. The Julia signatures, source links and per-owner provenance retain that distinction. Makie&#39;s real WGL extension documents <code>PerfChecker.performance_plot_html</code>; that Core binding is not an additional export of the extension. Web remains version 1.0.0 alongside Core 1.0.1.</p><p>Each inventory is relative to this site&#39;s <code>optional-api/</code> directory. Inventories remain separate because a shared Core binding can have different methods in different owners. They supplement Core&#39;s <code>objects.inv</code> without replacing entries. The corresponding <code>&lt;owner&gt;.toml</code> files in that directory record the source commit, Docs and method owners, signatures, source hashes and rendering inputs.</p><p>See <a href="./../guide/installation">installation</a> for source installation and compatible worker environments. Generating references does not start a server, open Pluto, render a plot, run a terminal interface or measure a hardware counter. LinuxPerf and LIKWID require their documented permissions and native prerequisites; their explicit Julia executor is not a native CLI, VS Code, Pluto or MCP selector.</p><p>The stable Core 1.0.0 site retains its own APIs. These 1.0.1 references are not injected into an explicit documentation-only refresh of that release.</p>',7)])])}const f=t(r,[["render",n]]);export{u as __pageData,f as default};
